// Track live Chrome children; remove a pid when we observe the
// process has exited (via waitpid/try_wait on a side channel),
// and on Drop only signal children we still consider ours.
launched_pids: Mutex<HashMap<u32, ()>>,

fn drop(&mut self) {
    let pids: Vec<u32> = self
        .launched_pids
        .lock()
        .unwrap_or_else(|e| e.into_inner())
        .keys()
        .copied()
        .collect();
    if pids.is_empty() { return; }
    // Verify the PID still belongs to a Chrome binary we started
    // (readlink /proc/<pid>/exe on Linux, GetModuleFileName on
    // Windows) before signalling, so PID reuse cannot kill an
    // unrelated process the daemon has no authority over.
    for pid in pids { /* verify + kill as above */ }
}

