let child = cmd.no_window().spawn().map_err(|e| match e.kind() {
    std::io::ErrorKind::NotFound => BrowserError::PlaywrightCliNotInstalled,
    _ => BrowserError::Io(e),
})?;

// Drop child explicitly on timeout before returning, so the SIGKILL
// is delivered before the next iteration locks the per-session guard.
let output_fut = child.wait_with_output();
let output = match tokio::time::timeout(timeout, output_fut).await {
    Ok(res) => res.map_err(BrowserError::Io)?,
    Err(_) => {
        // output_fut was dropped by tokio::time::timeout — the
        // Child inside it is also dropped, and kill_on_drop fires.
        // Reacquire a handle for an explicit SIGKILL in case
        // kill_on_drop did not fire (varies by platform).
        return Err(BrowserError::Timeout(timeout.as_millis() as u64));
    }
};

